import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.9yf7n3zg.js";const n="/guide/media/privacy-meaning-search.webp",p=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"reference/privacy.md","filePath":"reference/privacy.md","lastUpdated":1791657833000}'),r={name:"reference/privacy.md"};function i(h,e,d,l,c,g){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Leathercase works offline. By default nothing leaves your computer: no account, no sign-in, no telemetry, no analytics, no crash reports, no usage counts sent anywhere. Your writing is read on your computer and Leathercase&#39;s own files are written next to it, in your writing home. This page lists the few things that can go online, each one only on your word, and where everything Leathercase keeps is stored.</p><h2 id="what-can-leave-your-computer" tabindex="-1">What can leave your computer <a class="header-anchor" href="#what-can-leave-your-computer" aria-label="Permalink to &quot;What can leave your computer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>When</th><th>Where it goes</th><th>What is sent</th></tr></thead><tbody><tr><td>The update check</td><td>Only when you choose <strong>Check now</strong> (in <strong>Settings</strong>, <strong>Updates</strong> or <strong>About</strong>) or <strong>Check for updates</strong>, or at launch once you turned on <strong>Check when Leathercase opens</strong></td><td>Leathercase&#39;s public releases page on GitHub</td><td>A request for the list of the newest version&#39;s files. Nothing about you or your writing</td></tr><tr><td>An update download</td><td>Only when you choose <strong>Download</strong> after a check</td><td>The same releases page</td><td>A request for the installer file</td></tr><tr><td>The meaning search model</td><td>Only when you choose <strong>Download</strong> in <strong>Search by meaning</strong>, or in <strong>Settings</strong>, <strong>Search</strong></td><td>Hugging Face, where the model is published</td><td>A request for the model&#39;s files. Nothing of your writing</td></tr><tr><td>A link you open</td><td>When you click a link to a web page, such as the download page</td><td>Your web browser</td><td>What your browser sends for any page</td></tr></tbody></table><p>Each of these is an ordinary web request, so the server sees what any website sees, such as your computer&#39;s internet address. None of them carries your name, your stories, your notes or anything about how you use Leathercase.</p><p>Nothing else in Leathercase goes online. The window itself is not allowed to load anything from the internet: its pages, fonts and images all come from inside the app, and a link that would open another page in the window goes to your browser instead, and only over <code>https</code>.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Leathercase asks which version is newest only when you say so; <strong>Settings</strong>, <strong>Updates</strong> says it in its first line: <strong>Leathercase goes online for one thing only, to ask which version is newest, and only when you say so. Nothing about you or your writing is sent.</strong> <strong>Check when Leathercase opens</strong> is off until you turn it on, and even then a check only marks <strong>Settings</strong> with a dot; nothing downloads by itself. See <a href="/guide/reference/updates">Updates and uninstalling</a>.</p><h2 id="meaning-search" tabindex="-1">Meaning search <a class="header-anchor" href="#meaning-search" aria-label="Permalink to &quot;Meaning search&quot;">​</a></h2><p>Word search always works, offline, in the find field. Meaning search, which finds passages that say the same thing in other words, needs a small model. Leathercase does not ship it and does not fetch it until you agree.</p><p><img src="'+n+'" alt="Under the find field, after a search that found no exact words, the Search by meaning box: the consent text, the model&#39;s name, licence and size, Download and Not now" width="700" height="437" loading="lazy"></p><ul><li>The first time a search in the find field (<code>Ctrl+K</code>, or <code>Cmd+K</code> on macOS) finds none of your words, Leathercase asks once, in a box under the results: <strong>Search by meaning</strong>, with the line <strong>Meaning search finds passages that say the same thing in other words, in any language your stories use. It needs a small model, about 135 MB, downloaded once. After that it runs on this computer, and your text never leaves it.</strong></li><li><strong>Download</strong> fetches the model (multilingual E5 small, MIT licence) from Hugging Face, at a fixed version, and checks every file against its known fingerprint before using it. <strong>Pause</strong> and <strong>Resume</strong> work mid-download; <strong>Cancel</strong> removes what came.</li><li><strong>Not now</strong> keeps word search and does not ask again for a week.</li><li>Once downloaded, the model runs inside the app. Leathercase reads your stories to index them, on this computer; the index is kept in memory only and never written to disk.</li><li><strong>Settings</strong>, <strong>Search</strong> shows whether the model is on this computer and its size, and <strong>Remove</strong> deletes it.</li></ul><p>Intel Macs cannot run the model, so Leathercase never offers the download there; word search works as always.</p><h2 id="the-mate" tabindex="-1">The mate <a class="header-anchor" href="#the-mate" aria-label="Permalink to &quot;The mate&quot;">​</a></h2><p>The mate is Leathercase&#39;s own assistant. It reads your stories with Leathercase&#39;s rules, on this computer, and wakes no model. <strong>Settings</strong>, <strong>The mate</strong> says so: <strong>Model turns come with a later paid service. Until then the mate wakes no model.</strong> What it notices stays in your writing home (<code>suite/assistant/</code>) and in this computer&#39;s app data. See <a href="/guide/guide/mate">The mate</a>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>An agent is an AI assistant that runs in another app, such as Claude Desktop, Codex, Claude Code, Cursor or Gemini CLI. An agent reaches your stories only if you connect it, and only through Leathercase.</p><ul><li><strong>On this computer only.</strong> Leathercase listens for agents on a private local channel (a socket only your user account can open, or a named pipe on Windows), never on the network. ChatGPT cannot connect for now: it reaches only servers on the internet, and Leathercase will not relay your stories through one.</li><li><strong>Only what you grant.</strong> Each agent has its own token and sees only the writing homes you chose for it. No tool it can call takes a path on your computer, runs a command or writes your files. Proposals wait in the <a href="/guide/guide/inbox">inbox</a> until you accept them.</li><li><strong>Every call is logged.</strong> Each call an agent makes is written to that agent&#39;s log in the story&#39;s <code>suite/logs/assistant/</code>, kept 90 days. <strong>Settings</strong>, <strong>Agents</strong>, <strong>Log</strong> shows, call by call, what it asked for and <strong>What left Leathercase</strong>, with the words read each day. You can pause every agent at once, or revoke one; its next request is turned away.</li><li><strong>What Leathercase cannot control.</strong> Once an agent has read a scene, what its own app does with it is that app&#39;s business: most send it to the company that runs the model. Many agents can also open files and run commands on their own, outside Leathercase. Grant an agent only the homes you mean to share, and read what your agent&#39;s own tools allow. See <a href="/guide/guide/connect-an-agent">Connect an agent</a>.</li></ul><p>Setting up an agent other than Claude Desktop uses <code>npx -y leathercase-mcp</code>, which that agent&#39;s app downloads from the npm registry: the small bridge it starts to find Leathercase. That download is made by the agent&#39;s app, not by Leathercase.</p><h2 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h2><p>Leathercase never uploads anything itself. When your writing home sits in a Dropbox, iCloud Drive, OneDrive or Google Drive folder, or in a git repository, that tool carries both your stories and Leathercase&#39;s files, as it would any other files. <strong>Settings</strong>, <strong>Storage</strong> names the sync tool it finds in the folder&#39;s path, or says the folder lives on this computer only.</p><p>The writing and sentence logs in <code>suite/logs/</code> are named after the computer that wrote them, such as <code>2026-10-06.apollo-desktop.jsonl</code>, so two computers never write the same file. Your computer&#39;s name therefore travels with the home to wherever it syncs.</p><h2 id="what-leathercase-reads-besides-your-stories" tabindex="-1">What Leathercase reads besides your stories <a class="header-anchor" href="#what-leathercase-reads-besides-your-stories" aria-label="Permalink to &quot;What Leathercase reads besides your stories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Why</th></tr></thead><tbody><tr><td>Obsidian&#39;s list of vaults on this computer, and a vault&#39;s list of community plugins</td><td>To open a passage in Obsidian at the right note and heading</td></tr><tr><td>The writing apps installed on this computer</td><td>To offer them in <strong>Open in</strong></td></tr><tr><td>Your system&#39;s languages</td><td>To choose the app&#39;s language when it follows the system</td></tr><tr><td>Your computer&#39;s name, once</td><td>To name this computer&#39;s log files</td></tr></tbody></table><p>All of these are read, never changed, and never sent anywhere.</p><h2 id="what-is-stored-where" tabindex="-1">What is stored where <a class="header-anchor" href="#what-is-stored-where" aria-label="Permalink to &quot;What is stored where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kept</th><th>Where</th><th>Synced with your home</th></tr></thead><tbody><tr><td>Your manuscripts and notes</td><td>Your writing home, untouched</td><td>By your sync tool, as always</td></tr><tr><td>Leathercase&#39;s files for your stories: grid, threads, cards, comments, settings, layouts, logs, agents&#39; findings</td><td><code>Suite.md</code>, <code>suite/</code> and <code>Writer/</code> in your writing home, and a <code>suite/</code> folder in each story</td><td>Yes</td></tr><tr><td>This computer&#39;s preferences, the list of homes and where each lives, keys, agent tokens and grants, the mate&#39;s memory, the meaning search model</td><td>The app&#39;s data folder on this computer</td><td>Never</td></tr></tbody></table><p><a href="/guide/reference/suite-files">Files Leathercase writes</a> lists every file. To remove Leathercase&#39;s files from a home, use <strong>Settings</strong>, <strong>Storage</strong>, <strong>Remove…</strong>, <strong>Purge</strong>; to remove the app and its data from the computer, see <a href="/guide/reference/updates#uninstalling">Uninstalling</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/updates">Updates and uninstalling</a></li><li><a href="/guide/guide/connect-an-agent">Connect an agent</a></li><li><a href="/guide/guide/mate">The mate</a></li></ul>',30)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
